import AsyncKit
import Foundation
import Logging
import NIOPosix
import PostgresKit
import SQLKit

/// The database DATABASE_URL names, through PostgresKit. It never migrates: the database already exists.
public final class AppDatabase: Sendable {
    public static let defaultURL = "postgres://app:app@localhost:5432/app"

    // The pool locks what it keeps, though AsyncKit does not declare it Sendable
    private nonisolated(unsafe) let pool: EventLoopGroupConnectionPool<PostgresConnectionSource>
    /// What the repositories run their SQL on.
    public let database: Db

    /// The database at url (DATABASE_URL, or defaultURL, by default).
    public convenience init(url: String = ProcessInfo.processInfo.environment["DATABASE_URL"] ?? AppDatabase.defaultURL) throws {
        try self.init(configuration: SQLPostgresConfiguration(url: url))
    }

    /// The database a configuration names.
    public init(configuration: SQLPostgresConfiguration) {
        let source = PostgresConnectionSource(sqlConfiguration: configuration)
        let pool = EventLoopGroupConnectionPool(source: source, on: MultiThreadedEventLoopGroup.singleton)
        self.pool = pool
        self.database = Db(sql: pool.database(logger: Logger(label: "app.database")).sql())
    }

    /// Closes the connections.
    public func shutdown() async {
        try? await pool.shutdownAsync()
    }
}

/// What the repositories run their SQL on: the pool, or the connection of a transaction.
public struct Db: Sendable {
    public let sql: any SQLDatabase
    private let inTransaction: Bool

    init(sql: any SQLDatabase, inTransaction: Bool = false) {
        self.sql = sql
        self.inTransaction = inTransaction
    }

    /// Runs work in a transaction, committed when it ends and undone when it throws; it joins the one already open.
    public func transaction<T: Sendable>(_ work: @escaping @Sendable (Db) async throws -> T) async throws -> T {
        if inTransaction { return try await work(self) }
        return try await sql.withSession { session in
            try await session.raw("BEGIN").run()
            do {
                let result = try await work(Db(sql: session, inTransaction: true))
                try await session.raw("COMMIT").run()
                return result
            } catch {
                try? await session.raw("ROLLBACK").run()
                throw error
            }
        }
    }
}

/// A value that may be nil, bound to a statement.
func bound<T: Encodable & Sendable>(_ value: T?) -> any SQLExpression {
    if let value { SQLBind(value) } else { SQLLiteral.null }
}

extension SQLRow {
    /// The value of a column, or nil.
    func optional<T: Decodable>(_ column: String, as type: T.Type) throws -> T? {
        try decodeNil(column: column) ? nil : decode(column: column, as: type)
    }
}

/// Whether the database refused a write: a unique value taken, a row still pointed to, a value against its rules.
func isRefusal(_ error: any Error) -> Bool {
    // SQLSTATE class 23: integrity constraint violation
    (error as? PSQLError)?.serverInfo?[.sqlState]?.hasPrefix("23") == true
}

/// A page of a list: the rows from an offset, and how many there are in all.
public struct Page<T: Sendable>: Sendable {
    public let items: [T]
    public let total: Int
    public let offset: Int
    public let limit: Int

    public init(items: [T], total: Int, offset: Int, limit: Int) {
        self.items = items
        self.total = total
        self.offset = offset
        self.limit = limit
    }

    /// The same page with every row turned into something else.
    public func map<R: Sendable>(_ transform: (T) throws -> R) rethrows -> Page<R> {
        Page<R>(items: try items.map(transform), total: total, offset: offset, limit: limit)
    }
}

/// A field of an update: absent (it keeps its value), or set to a value, which may be nil.
public enum Patch<T: Sendable>: Sendable {
    case absent
    case set(T)

    /// The value given, or nil when the field is absent.
    public var given: T? {
        switch self {
        case .absent: nil
        case .set(let value): value
        }
    }
}

/// The rows of a table kept in memory, shared by the copies of an in-memory repository.
actor MemoryRows<Row: Sendable> {
    private var rows: [Row] = []
    private var lastId = 0

    var all: [Row] { rows }

    /// The next number of a key the database would number.
    func nextId() -> Int {
        lastId += 1
        return lastId
    }

    /// Keeps a row, in place of the ones same tells apart.
    func store(_ row: Row, replacing same: @Sendable (Row) -> Bool) {
        rows.removeAll(where: same)
        rows.append(row)
    }

    func remove(where same: @Sendable (Row) -> Bool) {
        rows.removeAll(where: same)
    }
}

/// Orders two values that may be nil, nil first.
func less<T: Comparable>(_ a: T?, _ b: T?) -> Bool {
    switch (a, b) {
    case let (a?, b?): a < b
    case (nil, _?): true
    default: false
    }
}

