/// Checks the values against the rules of the "products" table, and the rows they point to; throws validationFailed with every problem.
fileprivate func validate(_ uow: any UnitOfWork, _ values: Values, _ current: Product?) async throws {
    let creating = current == nil
    var errors: [FieldError] = []
    if values.categoryId ?? nil == nil && (creating || values.categoryId != nil) {
        errors.append(FieldError("category_id", "is required"))
    }
    if let value = values.name ?? nil {
        if value.count > 100 {
            errors.append(FieldError("name", "is longer than 100 characters"))
        }
    } else if creating || values.name != nil {
        errors.append(FieldError("name", "is required"))
    }
    if values.price ?? nil == nil && (creating || values.price != nil) {
        errors.append(FieldError("price", "is required"))
    }
    if let value = values.status ?? nil {
        if value.count > 10 {
            errors.append(FieldError("status", "is longer than 10 characters"))
        }
        if !["draft", "live"].contains(value) {
            errors.append(FieldError("status", "must be one of: draft, live"))
        }
    } else if !creating && values.status != nil {
        errors.append(FieldError("status", "cannot be empty"))
    }
    if let categoryId = values.categoryId ?? current?.categoryId {
        if try await uow.categories.findById(categoryId) == nil {
            errors.append(FieldError("category_id", "no Category has this key"))
        }
    }
    if !errors.isEmpty { throw DomainError.validationFailed(entity: "Product", errors: errors) }
}

