/// What services depend on: a repository per table and a transaction. Each service operation runs in transaction(): committed when it ends, rolled back when it throws.
public protocol UnitOfWork: Sendable {
    var customers: any CustomerRepository { get }
    var categories: any CategoryRepository { get }
    var products: any ProductRepository { get }
    var tags: any TagRepository { get }
    var productTags: any ProductTagRepository { get }

    /// Runs work with the repositories of the transaction; commits when it ends, rolls back when it throws.
    func transaction<T: Sendable>(_ work: @escaping @Sendable (any UnitOfWork) async throws -> T) async throws -> T
}

/// The repositories over one database, and its transaction.
public struct SqlUnitOfWork: UnitOfWork {
    public let db: Db

    public init(db: Db) {
        self.db = db
    }

    public var customers: any CustomerRepository { SqlCustomerRepository(db: db) }

    public var categories: any CategoryRepository { SqlCategoryRepository(db: db) }

    public var products: any ProductRepository { SqlProductRepository(db: db) }

    public var tags: any TagRepository { SqlTagRepository(db: db) }

    public var productTags: any ProductTagRepository { SqlProductTagRepository(db: db) }

    /// Joins the transaction already open, or opens one.
    public func transaction<T: Sendable>(_ work: @escaping @Sendable (any UnitOfWork) async throws -> T) async throws -> T {
        try await db.transaction { transaction in try await work(SqlUnitOfWork(db: transaction)) }
    }
}

/// The in-memory repositories, for tests and for trying the services without a database.
public final class MemoryUnitOfWork: UnitOfWork {
    public let customers: any CustomerRepository = MemoryCustomerRepository()
    public let categories: any CategoryRepository = MemoryCategoryRepository()
    public let products: any ProductRepository = MemoryProductRepository()
    public let tags: any TagRepository = MemoryTagRepository()
    public let productTags: any ProductTagRepository = MemoryProductTagRepository()

    public init() {}

    /// Memory has no transactions: changes are kept as they are made.
    public func transaction<T: Sendable>(_ work: @escaping @Sendable (any UnitOfWork) async throws -> T) async throws -> T {
        try await work(self)
    }
}

