import Foundation
import SQLKit
import Testing
@testable import SwiftSqlPostgresqlConversionsDtos

/// Every test is in this suite, one after another: they all empty the same database.
@Suite(.serialized) struct DataTests {}

/// The test database: the PostgreSQL database TEST_DATABASE_URL names, created again before every test.
enum TestDatabase {
    /// Runs body with the repositories over the test database, with every table dropped and created again first.
    static func with(_ body: (SqlUnitOfWork) async throws -> Void) async throws {
        // The tables are written for one kind of database: the tests cannot fall back to SQLite
        let url = try #require(ProcessInfo.processInfo.environment["TEST_DATABASE_URL"], "The database tests need a disposable PostgreSQL database: set TEST_DATABASE_URL (it is emptied)")
        let app = try AppDatabase(url: url)
        do {
            try await recreate(app.database)
            try await body(SqlUnitOfWork(db: app.database))
        } catch {
            await app.shutdown()
            throw error
        }
        await app.shutdown()
    }

    /// Drops every table and creates them again; on one connection, as MySQL turns its foreign key checks off for the connection that asks.
    private static func recreate(_ db: Db) async throws {
        try await db.sql.withSession { session in
            for statement in drop + create { try await session.raw("\(unsafeRaw: statement)").run() }
        }
    }

    /// Removes every table, so the database starts empty.
    private static let drop: [String] = [
        "DROP TABLE IF EXISTS \"product_tags\" CASCADE",
        "DROP TABLE IF EXISTS \"tags\" CASCADE",
        "DROP TABLE IF EXISTS \"products\" CASCADE",
        "DROP TABLE IF EXISTS \"categories\" CASCADE",
        "DROP TABLE IF EXISTS \"customers\" CASCADE",
    ]

    /// Creates every table, in an order the database accepts.
    private static let create: [String] = [
        "CREATE TABLE \"customers\" (\n  \"id\" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,\n  \"email\" VARCHAR(120) NOT NULL,\n  \"password_hash\" TEXT NOT NULL,\n  \"created_at\" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (\"id\"),\n  UNIQUE (\"email\")\n)",
        "CREATE TABLE \"categories\" (\n  \"id\" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,\n  \"name\" VARCHAR(60) NOT NULL,\n  PRIMARY KEY (\"id\"),\n  UNIQUE (\"name\")\n)",
        "CREATE TABLE \"products\" (\n  \"id\" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,\n  \"category_id\" INTEGER NOT NULL,\n  \"name\" VARCHAR(100) NOT NULL,\n  \"price\" NUMERIC(10, 2) NOT NULL,\n  \"status\" VARCHAR(10) NOT NULL DEFAULT 'draft',\n  PRIMARY KEY (\"id\"),\n  CHECK (\"status\" IN ('draft', 'live')),\n  FOREIGN KEY (\"category_id\") REFERENCES \"categories\" (\"id\")\n)",
        "CREATE TABLE \"tags\" (\n  \"id\" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,\n  \"label\" VARCHAR(30) NOT NULL,\n  PRIMARY KEY (\"id\")\n)",
        "CREATE TABLE \"product_tags\" (\n  \"product_id\" BIGINT NOT NULL,\n  \"tag_id\" INTEGER NOT NULL,\n  PRIMARY KEY (\"product_id\", \"tag_id\"),\n  FOREIGN KEY (\"product_id\") REFERENCES \"products\" (\"id\"),\n  FOREIGN KEY (\"tag_id\") REFERENCES \"tags\" (\"id\")\n)",
    ]
}

/// The DomainError work throws, or nil when it throws none.
func refusal<T>(_ work: () async throws -> T) async -> DomainError? {
    do {
        _ = try await work()
        return nil
    } catch let error as DomainError {
        return error
    } catch {
        return nil
    }
}

func isConflict(_ error: DomainError?) -> Bool {
    if case .some(.conflict) = error { true } else { false }
}

func isNotFound(_ error: DomainError?) -> Bool {
    if case .some(.notFound) = error { true } else { false }
}

extension DataTests {
    /// The tests run on the database they were asked to.
    @Suite struct DatabaseTests {
        @Test func isTheTestDatabase() async throws {
            try await TestDatabase.with { uow in
                let rows = try await uow.db.sql.raw("SELECT current_database()::text AS value").all()
                let value = try rows[0].decode(column: "value", as: String.self)
                let url = ProcessInfo.processInfo.environment["TEST_DATABASE_URL"] ?? ""
                #expect(url.split(separator: "/").last?.split(separator: "?").first.map(String.init) == value)
            }
        }
    }
}

